/*
  Custom Script for: Material Request
  Author: Your Name
  Description: Shows a loading overlay during submission for both single (form view)
               and multiple (list view) records.
*/

// =================================================================
// 1. HELPER FUNCTIONS TO SHOW/HIDE THE LOADING OVERLAY
// =================================================================
console.log("✅ material_request.js loaded successfully!");

function show_loading_overlay() {
	// Only add the overlay if it doesn't already exist
	if (!$('#custom-loading-overlay').length) {
		const sunny_gif_base64 = "data:image/gif;base64,";
	    $('body').append(`
		  <div id="custom-loading-overlay" style="
			position: fixed;
			top: 0; left: 0; right: 0; bottom: 0;
			background: rgba(255, 255, 255, 0.8);
			z-index: 9999;
			display: flex;
			align-items: center;
			justify-content: center;
		  ">
			<img src="${sunny_gif_base64}" alt="Loading..." style="width: 200px; height: 200px;" />
		  </div>
	    `);
	}
}

function hide_loading_overlay() {
	// Simply remove the overlay
	$('#custom-loading-overlay').remove();
}


// =================================================================
// 2. HANDLER FOR SINGLE DOCUMENT SUBMISSION (FROM FORM VIEW)
// =================================================================

frappe.ui.form.on('Material Request', {
	before_submit: function(frm) {
		console.log("before submiet start")
	    // This event fires only when submitting from the form view
	    show_loading_overlay();
	},
	on_submit: function(frm) {
	    // This event fires on successful submission from the form view
	    hide_loading_overlay();
	}
});


// =================================================================
// 3. WRAPPERS TO HIDE OVERLAY ON ANY ERROR OR MESSAGE
// (These are global and will work for both single and multi-submit)
// =================================================================

// Wrap frappe.throw to catch explicit server-side errors
frappe.throw = (function(original_throw) {
	return function(msg) {
		hide_loading_overlay();
		// Call the original function
		return original_throw.apply(this, arguments);
	};
})(frappe.throw);

// Wrap frappe.msgprint to catch validation errors and success messages
frappe.msgprint = (function(original_msgprint) {
	return function(msg) {
		hide_loading_overlay();
		// Call the original function
		return original_msgprint.apply(this, arguments);
	};
})(frappe.msgprint);

// Global listener for generic AJAX errors (e.g., server timeout, 500 errors)
$(document).on("ajaxError", function() {
	hide_loading_overlay();
});


