frappe.ui.form.on('Material Request', {
    refresh: function (frm) {
        toggle_chic_fields(frm);
    },

    items_on_form_rendered: function (frm) {
        toggle_chic_fields(frm);
    }
});

frappe.ui.form.on('Material Request Item', {
    item_code: function (frm) {
        toggle_chic_fields(frm);
    },

    items_remove: function (frm) {
        toggle_chic_fields(frm);
    }
});

function toggle_chic_fields(frm) {
    let show_fields = false;

    (frm.doc.items || []).forEach(row => {
        if (row.item_group === "CHIC WIP") {
            show_fields = true;
        }
    });

    frm.toggle_display('custom_submit_chic_flow', show_fields);
    frm.toggle_display('custom_batch_id', show_fields);
    frm.toggle_display('custom_note', show_fields);
}



frappe.ui.form.on('Material Request', {
    // This function triggers when the Button Field 'custom_submit_chic_flow' is clicked
    custom_submit_chic_flow: function(frm) {
        
        // 1. VALIDATION
        if (frm.doc.docstatus !== 0) {
            frappe.throw(__('Document is not in a submittable state.'));
            return;
        }

        if (frm.is_dirty()) {
            frappe.throw(__('Please save the document first.'));
            return;
        }

        if (!frm.doc.custom_batch_id) {
            frappe.throw(__('Please select Batch No before submitting.'));
            return;
        }

        // 2. CONFIRMATION
        frappe.confirm(
            __('Are you sure you want to Submit and create Work Orders?'),
            
            // YES CLICKED
            function() {
                // 3. DIRECT SERVER CALL
                // This calls the python method directly. 
                // It does NOT trigger the browser's standard submit flow.
                frappe.call({
                    method: "caf.caf.overrides.material_request.submit_chic_flow_action",
                    args: {
                        doc_name: frm.doc.name
                    },
                    freeze: true, // This blocks the screen so they can't click twice
                    freeze_message: __("Processing Chic Flow..."),
                    callback: function(r) {
                        if (!r.exc) {
                            frappe.show_alert({
                                message: __("Chic Flow Submitted Successfully"),
                                indicator: 'green'
                            });
                            // Reload to see the new submitted status
                            frm.reload_doc();
                        }
                    }
                });
            }
        );
    }
});


frappe.ui.form.on("Material Request", {

        onload(frm) {
            frm.set_query("custom_batch_id", function () {
                return {
                    filters: [
                        ["Batch", "item", "=", "General Chicken"],
                        ["Batch", "batch_qty", ">", 0],
                        ["Batch", "disabled", "=", 0],
                        ["Batch", "expiry_date", ">=", frappe.datetime.get_today()]
                    ]
                };
            });
        }
});
    
